def _identifier(name):
    plain = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode()
    words = re.findall(r"[A-Za-z0-9]+", plain)
    if not words:
        return "PRJ"
    if len(words) == 1:
        return words[0][:3].upper()
    return "".join(word[0] for word in words[:4]).upper()


def number_tasks(apps, schema_editor):
    Sector = apps.get_model("core", "Sector")
    Task = apps.get_model("core", "Task")
    for sector in Sector.objects.all():
        tasks = list(Task.objects.filter(sector=sector).order_by("created_at", "id"))
        for number, task in enumerate(tasks, start=1):
            task.sequence = number
        Task.objects.bulk_update(tasks, ["sequence"])
        sector.identifier = _identifier(sector.name)
        sector.task_counter = len(tasks)
        sector.save(update_fields=["identifier", "task_counter"])



